const desired = JSON.parse(msg.payload);
if (!Number.isInteger(desired.targetTemperature)) return null;
if (env.get('NR_OMIT_LATEST') === 'true' && desired.targetTemperature === 24) return null;
const deviation = env.get('NR_DEVIATION_VALUE');
if (desired.targetTemperature === 24 && deviation !== '') {
    const delay = Number(env.get('NR_DEVIATION_DELAY_MS'));
    setTimeout(() => {
        node.warn('negative control reported temperature=' + deviation);
        node.send({payload: JSON.stringify({temperature: Number(deviation)})});
    }, delay);
    node.warn('negative control reported temperature=24');
}
return {payload: JSON.stringify({temperature: desired.targetTemperature})};
